export const SCALE_STAGES = [
  { id: 1, label: "Authenticate and plan", detail: "Cognito identity and the protected API establish role and scope, then the server binds an immutable profile, seed, limits, and price evidence. A dedicated presenter identity proves TOTP." },
  { id: 2, label: "Run gate", detail: "The Scale Control function validates plan expiry, idempotency, one-active-run policy, the 100K proof prerequisite, and the cost envelope." },
  { id: 3, label: "Orchestrate", detail: "A Standard Step Functions workflow passes only the run identifier while durable state remains in the DynamoDB ledger." },
  { id: 4, label: "Buffer", detail: "SQS absorbs the partition burst, applies backpressure, retries transient failures, and isolates poison work in a dead letter queue." },
  { id: 5, label: "Generate and gate", detail: "Reserved-concurrency Lambda workers create deterministic related records, validate every row, curate passing data, and quarantine failures." },
  { id: 6, label: "Persist lake zones", detail: "KMS-encrypted S3 stores immutable landing data, curated JSON Lines, quarantine records, receipts, Parquet, and manifests." },
  { id: 7, label: "Catalog and convert", detail: "Six Glue tables expose run partitions. Lake Formation governs access and Athena converts the bounded run to Parquet under a 10 GiB scan cutoff." },
  { id: 8, label: "Merge intelligence", detail: "Finalization merges every idempotent Partition Receipt into full-corpus quality, topic, anomaly, performance, and cost evidence." },
  { id: 9, label: "Release and prove", detail: "The export queue builds an immutable checksummed release while Mission Control reads sanitized terminal evidence from the ledger." },
];

