export function componentsForView(view: ArchitectureView): ArchitectureComponent[] {
  return COMPONENTS.filter((component) => component.positions[view]);
}

export function connectionsForView(view: ArchitectureView): ArchitectureConnection[] {
  const visible = new Set(componentsForView(view).map((component) => component.id));
  return CONNECTIONS.filter((connection) => connection.views.includes(view) && visible.has(connection.source) && visible.has(connection.target));
}
